<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/safety_vote_phase2.php';

function sv2_campaign(int$id,bool$lock=false):?array{return db_row("SELECT c.*,v.VersionNo,v.CampaignType,v.PrivacyMode,v.TitleTh,v.TitleEn,v.Summary,v.Description,v.RulesText,v.ResultVisibility,v.PrivacyThreshold,v.Status VersionStatus,v.RowVersion VersionRowVersion FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=?".($lock?' FOR UPDATE':''),[$id]);}
function sv2_questions(int$versionId):array{$qs=db_rows("SELECT id,QuestionCode questionCode,QuestionType questionType,Title title,HelpText helpText,IsRequired isRequired,MinSelections minSelections,MaxSelections maxSelections,SortOrder sortOrder FROM SafetyVote_Questions WHERE CampaignVersionID=? AND Status='Active' ORDER BY SortOrder,id",[$versionId]);foreach($qs as&$q){$q['isRequired']=(bool)$q['isRequired'];$q['minSelections']=(int)$q['minSelections'];$q['maxSelections']=(int)$q['maxSelections'];$q['options']=db_rows("SELECT o.id,o.QuestionID questionId,o.OptionCode optionCode,o.Label label,o.Description description,o.FileID fileId,o.SortOrder sortOrder,c.id candidateId,c.EmployeeID candidateEmployeeId,c.DisplayName candidateName,c.ProfileText candidateProfile FROM SafetyVote_Options o LEFT JOIN SafetyVote_Candidates c ON c.OptionID=o.id AND c.Status='Active' WHERE o.QuestionID=? AND o.Status='Active' ORDER BY o.SortOrder,o.id",[$q['id']]);}unset($q);return$qs;}
function sv2_result(array$c):array{$qs=sv2_questions((int)$c['CurrentVersionID']);$answers=db_rows("SELECT a.OptionID FROM SafetyVote_BallotAnswers a JOIN SafetyVote_Ballots b ON b.id=a.BallotID WHERE b.CampaignVersionID=? AND b.Status='Accepted'",[$c['CurrentVersionID']]);$n=db_row("SELECT (SELECT EligibleCount FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY SnapshotNo DESC LIMIT 1) eligible,(SELECT COUNT(*) FROM SafetyVote_Participation WHERE CampaignVersionID=? AND State='submitted') participated",[$c['CurrentVersionID'],$c['CurrentVersionID']])?:[];$counts=[];foreach($answers as$a)$counts[(int)$a['OptionID']]=($counts[(int)$a['OptionID']]??0)+1;$participated=(int)($n['participated']??0);foreach($qs as&$q)foreach($q['options']as&$o){$o['count']=$counts[(int)$o['id']]??0;$o['percentage']=$participated?round($o['count']/$participated*100,2):0;}unset($q,$o);$eligible=(int)($n['eligible']??0);return['eligibleCount'=>$eligible,'participationCount'=>$participated,'turnoutPct'=>$eligible?round($participated/$eligible*100,2):0,'questions'=>$qs];}
function sv2_audit(array$user,string$action,int$id,string$detail,array$meta=[]):void{sv_audit($user,$action,'SafetyVote_Campaign',(string)$id,$detail,$meta,$id,null);}

function handle_safety_vote_phase2_routes(string$method,string$path):bool{
    if(strpos($path,'/safety-vote/')!==0)return false;$user=require_user();
    $builder=route_params($path,'/safety-vote/admin/campaigns/:id/builder');
    $freeze=route_params($path,'/safety-vote/admin/campaigns/:id/eligibility/freeze');
    $life=route_params($path,'/safety-vote/admin/campaigns/:id/lifecycle/:command');
    $detail=route_params($path,'/safety-vote/campaigns/:id');
    $elig=route_params($path,'/safety-vote/campaigns/:id/eligibility');
    $submit=route_params($path,'/safety-vote/campaigns/:id/ballot/submit');
    $results=route_params($path,'/safety-vote/campaigns/:id/results');
    $dashboard=route_params($path,'/safety-vote/admin/campaigns/:id/dashboard');
    $export=route_params($path,'/safety-vote/admin/campaigns/:id/exports/data');
    $matched=$builder!==null||$freeze!==null||$life!==null||$detail!==null||$elig!==null||$submit!==null||$results!==null||$dashboard!==null||$export!==null||$path==='/safety-vote/me/campaigns';
    if(!$matched)return false;sv_require_schema();
    if($builder!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$c=sv2_campaign((int)$builder['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);json_response(['success'=>true,'data'=>['questions'=>sv2_questions((int)$c['CurrentVersionID'])]]);}
    if($builder!==null&&$method==='PUT'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$id=sv2_int($builder['id']);$body=json_body();$fileIds=[];foreach(($body['questions']??[])as$q)foreach(($q['options']??[])as$o){$fid=sv2_int($o['fileId']??null);if($fid)$fileIds[$fid]=true;}if($fileIds){$marks=implode(',',array_fill(0,count($fileIds),'?'));$params=array_merge([$id],array_keys($fileIds));$row=db_row("SELECT COUNT(*) total FROM SafetyVote_Files WHERE CampaignID=? AND Status='Active' AND id IN ($marks)",$params);if((int)($row['total']??0)!==count($fileIds))json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Every option image must be an active private file from this campaign.'],400);}$parsed=sv2_builder($body['questions']??null);if(!$id||!$parsed['ok'])json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Question builder is invalid.','details'=>$parsed['errors']],400);$pdo=db();$pdo->beginTransaction();try{$c=sv2_campaign($id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if($c['Status']!=='Draft'||$c['VersionStatus']!=='Draft'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Builder is editable only in Draft.'],409);}$pdo->prepare('DELETE c FROM SafetyVote_Candidates c JOIN SafetyVote_Options o ON o.id=c.OptionID JOIN SafetyVote_Questions q ON q.id=o.QuestionID WHERE q.CampaignVersionID=?')->execute([$c['CurrentVersionID']]);$pdo->prepare('DELETE o FROM SafetyVote_Options o JOIN SafetyVote_Questions q ON q.id=o.QuestionID WHERE q.CampaignVersionID=?')->execute([$c['CurrentVersionID']]);$pdo->prepare('DELETE FROM SafetyVote_Questions WHERE CampaignVersionID=?')->execute([$c['CurrentVersionID']]);$qstmt=$pdo->prepare('INSERT INTO SafetyVote_Questions(CampaignVersionID,QuestionCode,QuestionType,Title,HelpText,IsRequired,MinSelections,MaxSelections,SortOrder,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$ostmt=$pdo->prepare('INSERT INTO SafetyVote_Options(QuestionID,OptionCode,Label,Description,FileID,SortOrder,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?)');foreach($parsed['questions']as$q){$qstmt->execute([$c['CurrentVersionID'],$q['questionCode'],$q['questionType'],$q['title'],$q['helpText'],$q['isRequired']?1:0,$q['minSelections'],$q['maxSelections'],$q['sortOrder'],sv_actor($user),sv_actor($user)]);$qid=(int)$pdo->lastInsertId();foreach($q['options']as$o)$ostmt->execute([$qid,$o['optionCode'],$o['label'],$o['description'],$o['fileId'],$o['sortOrder'],sv_actor($user),sv_actor($user)]);}$pdo->commit();$hash=sv2_hash($parsed['questions']);sv2_audit($user,'SAFETY_VOTE_BUILDER_UPDATE',$id,'questions='.count($parsed['questions']),['builderHash'=>$hash]);json_response(['success'=>true,'data'=>['questions'=>sv2_questions((int)$c['CurrentVersionID']),'builderHash'=>$hash]]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'BUILDER_SAVE_FAILED','message'=>'Unable to save question builder.'],500);}}
    if($freeze!==null&&$method==='POST'){sv_require_permission($user,'SAFETY_VOTE_ELIGIBILITY_MANAGE');$id=sv2_int($freeze['id']);$body=json_body();$reason=sv2_text($body['reason']??'Phase 2 preflight',500);$pdo=db();$pdo->beginTransaction();try{$c=sv2_campaign((int)$id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if($c['Status']!=='Draft'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Eligibility can freeze only in Draft.'],409);}$raw=db_rows("SELECT RuleGroup ruleGroup,RuleOrder ruleOrder,Effect effect,AttributeKey attributeKey,Operator operator,ValuesJson,Reason reason FROM SafetyVote_EligibilityRules WHERE CampaignVersionID=? AND IsActive=1 ORDER BY RuleGroup,RuleOrder,id",[$c['CurrentVersionID']]);foreach($raw as&$r)$r['values']=json_decode((string)$r['ValuesJson'],true)?:[];unset($r);$parsed=sv_rules($raw);if(!$parsed['ok']||!$parsed['rules']){$pdo->rollBack();json_response(['success'=>false,'code'=>'PREFLIGHT_FAILED','message'=>'At least one valid eligibility rule is required.'],422);}$master=sv_master_projection();$eligible=sv_evaluate($parsed['rules'],$master['employees']);if(!$eligible){$pdo->rollBack();json_response(['success'=>false,'code'=>'PREFLIGHT_FAILED','message'=>'Eligibility produced no voters.'],422);}$pdo->prepare("UPDATE SafetyVote_EligibilitySnapshots SET Status='superseded' WHERE CampaignVersionID=? AND Status='frozen'")->execute([$c['CurrentVersionID']]);$n=db_row('SELECT COALESCE(MAX(SnapshotNo),0)+1 no FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=?',[$c['CurrentVersionID']]);$ruleHash=sv_hash($parsed['rules']);$rowsHash=sv2_rows_hash($eligible);$stmt=$pdo->prepare("INSERT INTO SafetyVote_EligibilitySnapshots(CampaignVersionID,SnapshotNo,Status,RuleHash,RowsHash,EligibleCount,AccountReadyCount,WarningCount,FrozenAt,FrozenBy,Reason,CreatedBy) VALUES(?,?,'frozen',?,?,?,?,?,NOW(),?,?,?)");$stmt->execute([$c['CurrentVersionID'],$n['no'],$ruleHash,$rowsHash,count($eligible),count(array_filter($eligible,fn($e)=>$e['accountReady'])),array_sum(array_map(fn($e)=>count($e['masterWarnings']),$eligible)),sv_actor($user),$reason,sv_actor($user)]);$sid=(int)$pdo->lastInsertId();$v=$pdo->prepare('INSERT INTO SafetyVote_EligibleVoters(SnapshotID,EmployeeID,EmployeeNameSnapshot,DepartmentIDSnapshot,DepartmentNameSnapshot,SafetyUnitIDSnapshot,SafetyUnitNameSnapshot,PositionIDSnapshot,PositionNameSnapshot,RoleSnapshot,TeamSnapshot,MasterPresent,AccountReady,EligibilityState,InclusionSource,InclusionReason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($eligible as$e)$v->execute([$sid,$e['employeeId'],$e['employeeName'],$e['departmentId'],$e['departmentName'],$e['safetyUnitId'],$e['safetyUnitName'],$e['positionId'],$e['positionName'],$e['role'],$e['team'],1,$e['accountReady']?1:0,'eligible',$e['inclusionSource'],$e['inclusionReason']]);$pdo->commit();sv2_audit($user,'SAFETY_VOTE_ELIGIBILITY_FREEZE',$id,$reason,['snapshotId'=>$sid,'eligibleCount'=>count($eligible),'ruleHash'=>$ruleHash,'rowsHash'=>$rowsHash]);json_response(['success'=>true,'data'=>['snapshotId'=>$sid,'snapshotNo'=>(int)$n['no'],'eligibleCount'=>count($eligible),'ruleHash'=>$ruleHash,'rowsHash'=>$rowsHash]],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'MASTER_DATA_INVALID','message'=>'Unable to freeze eligibility.'],503);}}
    if($life!==null&&$method==='POST'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$id=sv2_int($life['id']);$map=['open'=>'Open','close'=>'Closed','publish'=>'Published'];$to=$map[$life['command']]??null;if(!$id||!$to)json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Unsupported lifecycle command.'],400);$pdo=db();$pdo->beginTransaction();try{$c=sv2_campaign($id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if(!sv2_transition($c['Status'],$to)){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Invalid lifecycle transition.'],409);}if($to==='Open'){if(!db_row("SELECT id FROM SafetyVote_Questions WHERE CampaignVersionID=? AND Status='Active' LIMIT 1",[$c['CurrentVersionID']])||!db_row("SELECT id FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' LIMIT 1",[$c['CurrentVersionID']])){$pdo->rollBack();json_response(['success'=>false,'code'=>'PREFLIGHT_FAILED','message'=>'Questions and frozen eligibility are required.'],422);}}$pdo->prepare("UPDATE SafetyVote_Campaigns SET Status=?,OpenedAt=IF(?='Open',NOW(),OpenedAt),ClosedAt=IF(?='Closed',NOW(),ClosedAt),PublishedAt=IF(?='Published',NOW(),PublishedAt),UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([$to,$to,$to,$to,sv_actor($user),$id]);if($to==='Open')$pdo->prepare("UPDATE SafetyVote_CampaignVersions SET Status='Frozen',FrozenAt=NOW(),FrozenBy=?,ConfigHash=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([sv_actor($user),sv2_hash(sv2_questions((int)$c['CurrentVersionID'])),sv_actor($user),$c['CurrentVersionID']]);$pdo->commit();sv2_audit($user,'SAFETY_VOTE_CAMPAIGN_'.strtoupper($to),$id,'from='.$c['Status'].'; to='.$to);json_response(['success'=>true,'data'=>['id'=>$id,'status'=>$to]]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'LIFECYCLE_FAILED','message'=>'Unable to change campaign state.'],500);}}
    if($path==='/safety-vote/me/campaigns'&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_VIEW');$rows=db_rows("SELECT c.id,c.CampaignCode,c.Status,v.TitleTh,v.Summary,v.CampaignType,v.PrivacyMode,v.OpenAt,v.CloseAt,p.State ParticipationState FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID JOIN SafetyVote_EligibilitySnapshots s ON s.CampaignVersionID=v.id AND s.Status='frozen' JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id AND e.EmployeeID=? LEFT JOIN SafetyVote_Participation p ON p.CampaignVersionID=v.id AND p.EmployeeID=? WHERE c.Status IN ('Open','Closed','Published') ORDER BY c.UpdatedAt DESC",[sv_actor($user),sv_actor($user)]);json_response(['success'=>true,'data'=>['rows'=>$rows,'total'=>count($rows)]]);}
    if($elig!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_VIEW');$c=sv2_campaign((int)$elig['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);$e=db_row("SELECT s.SnapshotNo,p.State FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id LEFT JOIN SafetyVote_Participation p ON p.CampaignVersionID=s.CampaignVersionID AND p.EmployeeID=e.EmployeeID WHERE s.CampaignVersionID=? AND s.Status='frozen' AND e.EmployeeID=? LIMIT 1",[$c['CurrentVersionID'],sv_actor($user)]);json_response(['success'=>true,'data'=>['eligible'=>(bool)$e,'state'=>$e?'eligible':'ineligible','snapshotNo'=>$e?(int)$e['SnapshotNo']:null,'canSubmit'=>(bool)($e&&$c['Status']==='Open'&&!$e['State']),'reasonCode'=>$e?'RULE_MATCH':'NOT_IN_FROZEN_SNAPSHOT']]);}
    if($detail!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_VIEW');$c=sv2_campaign((int)$detail['id']);if(!$c||!in_array($c['Status'],['Open','Closed','Published'],true))json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);$e=db_row("SELECT e.*,s.SnapshotNo FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id WHERE s.CampaignVersionID=? AND s.Status='frozen' AND e.EmployeeID=? LIMIT 1",[$c['CurrentVersionID'],sv_actor($user)]);if(!$e)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_ELIGIBLE','message'=>'You are not eligible for this campaign.'],403);$p=db_row('SELECT State,SubmittedAt FROM SafetyVote_Participation WHERE CampaignVersionID=? AND EmployeeID=?',[$c['CurrentVersionID'],sv_actor($user)]);json_response(['success'=>true,'data'=>['campaign'=>$c,'questions'=>sv2_questions((int)$c['CurrentVersionID']),'eligibility'=>['eligible'=>true,'snapshotNo'=>(int)$e['SnapshotNo']],'participation'=>$p?:['State'=>'not_started'],'canSubmit'=>$c['Status']==='Open'&&!$p]]);}
    if($submit!==null&&$method==='POST'){sv_require_permission($user,'SAFETY_VOTE_VIEW');global$config;$id=sv2_int($submit['id']);$key=sv2_text($_SERVER['HTTP_IDEMPOTENCY_KEY']??'',160);if(!$id||strlen($key)<16)json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'A valid Idempotency-Key is required.'],400);$body=json_body();$pdo=db();$pdo->beginTransaction();try{$c=sv2_campaign($id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if($c['Status']!=='Open'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Campaign is not open.'],409);}$qs=sv2_questions((int)$c['CurrentVersionID']);$parsed=sv2_answers($qs,$body['answers']??null);$fingerprint=sv2_hash(['version'=>$body['campaignVersion']??null,'answers'=>$parsed['answers']]);if(!$parsed['ok']||(int)($body['campaignVersion']??0)!==(int)$c['VersionNo']||($body['acknowledgedRules']??false)!==true){$pdo->rollBack();json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Ballot is invalid.','details'=>$parsed['errors']],400);}$keyHash=hash_hmac('sha256',$key,(string)$config['jwt_secret']);$replay=db_row("SELECT RequestFingerprint,ResponseReference FROM SafetyVote_RequestKeys WHERE CampaignVersionID=? AND ActorEmployeeID=? AND Operation='ballot_submit' AND RequestKeyHash=? FOR UPDATE",[$c['CurrentVersionID'],sv_actor($user),$keyHash]);if($replay){$pdo->rollBack();if($replay['RequestFingerprint']!==$fingerprint)json_response(['success'=>false,'code'=>'IDEMPOTENCY_CONFLICT','message'=>'Idempotency key was used for another request.'],409);json_response(['success'=>true,'data'=>['accepted'=>true,'participationState'=>'submitted','receiptCode'=>$replay['ResponseReference'],'canEdit'=>false,'replayed'=>true]]);}$eligible=db_row("SELECT e.SnapshotID FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id WHERE s.CampaignVersionID=? AND s.Status='frozen' AND e.EmployeeID=? LIMIT 1 FOR UPDATE",[$c['CurrentVersionID'],sv_actor($user)]);if(!$eligible){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_ELIGIBLE','message'=>'You are not eligible for this campaign.'],403);}if(db_row('SELECT id FROM SafetyVote_Participation WHERE CampaignVersionID=? AND EmployeeID=? FOR UPDATE',[$c['CurrentVersionID'],sv_actor($user)])){$pdo->rollBack();json_response(['success'=>false,'code'=>'BALLOT_ALREADY_SUBMITTED','message'=>'A ballot was already submitted.'],409);}$receipt='SV-'.strtoupper(bin2hex(random_bytes(9)));$pdo->prepare("INSERT INTO SafetyVote_RequestKeys(CampaignVersionID,ActorEmployeeID,RequestKeyHash,Operation,RequestFingerprint,ResponseCode,ResponseReference,ExpiresAt) VALUES(?,?,?,'ballot_submit',?,200,?,DATE_ADD(NOW(),INTERVAL 7 DAY))")->execute([$c['CurrentVersionID'],sv_actor($user),$keyHash,$fingerprint,$receipt]);$pdo->prepare("INSERT INTO SafetyVote_Ballots(CampaignVersionID,PrivacyModeSnapshot,CanonicalBallotHash,IdempotencyHash,SchemaVersion) VALUES(?,?,?,?,?)")->execute([$c['CurrentVersionID'],$c['PrivacyMode'],sv2_hash($parsed['answers']),$keyHash,'2026-10-08-phase2-r1']);$bid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE SafetyVote_Ballots SET BallotSequence=id WHERE id=?')->execute([$bid]);$stmt=$pdo->prepare('INSERT INTO SafetyVote_BallotAnswers(BallotID,QuestionID,OptionID,AnswerOrder) VALUES(?,?,?,?)');foreach($parsed['answers']as$a)foreach($a['optionIds']as$i=>$oid)$stmt->execute([$bid,$a['questionId'],$oid,$i+1]);if(in_array($c['PrivacyMode'],['identified','confidential'],true))$pdo->prepare('INSERT INTO SafetyVote_BallotIdentities(BallotID,EmployeeID,IdentityMode) VALUES(?,?,?)')->execute([$bid,sv_actor($user),$c['PrivacyMode']]);$pdo->prepare("INSERT INTO SafetyVote_Participation(CampaignID,CampaignVersionID,SnapshotID,EmployeeID,State,AttemptCount,FirstStartedAt,SubmittedAt,LastActivityAt,ReceiptCodeHash) VALUES(?,?,?,?,'submitted',1,NOW(),NOW(),NOW(),SHA2(?,256))")->execute([$id,$c['CurrentVersionID'],$eligible['SnapshotID'],sv_actor($user),$receipt]);$pdo->commit();json_response(['success'=>true,'data'=>['accepted'=>true,'participationState'=>'submitted','receiptCode'=>$receipt,'submittedAt'=>date(DATE_ATOM),'canEdit'=>false]],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();if((string)$e->getCode()==='23000')json_response(['success'=>false,'code'=>'BALLOT_ALREADY_SUBMITTED','message'=>'A ballot was already submitted.'],409);json_response(['success'=>false,'code'=>'BALLOT_SUBMIT_FAILED','message'=>'Unable to accept ballot.'],500);}}
    if($results!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_VIEW');$c=sv2_campaign((int)$results['id']);if(!$c||!in_array($c['Status'],['Closed','Published'],true))json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Results are not available.'],404);json_response(['success'=>true,'data'=>sv2_result($c)]);}
    if($dashboard!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_RESULT_VIEW');$c=sv2_campaign((int)$dashboard['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);json_response(['success'=>true,'data'=>sv2_result($c)]);}
    if($export!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_EXPORT');$c=sv2_campaign((int)$export['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);json_response(['success'=>true,'data'=>array_merge(['campaign'=>['id'=>$c['id'],'code'=>$c['CampaignCode'],'title'=>$c['TitleTh'],'status'=>$c['Status']]],sv2_result($c),['exportedAt'=>date(DATE_ATOM)])]);}
    return false;
}
